from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
motor = Motor(Port.C, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.D, Direction.CLOCKWISE)
drive_base = DriveBase(motor, motor_2, 56, 128)
back_arm = Motor(Port.A, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.E, Direction.CLOCKWISE)


# The main program starts here.
drive_base.settings(straight_speed=500)
drive_base.straight(500)
drive_base.turn(90)
drive_base.straight(60)
drive_base.turn(-90)
drive_base.straight(140)
front_motor.run_angle(1000, 360)
drive_base.straight(-100)
front_motor.run_angle(1000, -350)
drive_base.straight(100)
front_motor.run_angle(1000, 360)
front_motor.run_angle(1000, -100)
drive_base.straight(-100)
